(function(){window.PhysicaRankPyqNeet_physics_semiconductorelectronics=[{id:"neet-2026-q003",pn:3,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Semiconductor Electronics",st:"p-n junction biasing, depletion width",q:"Three identical p-n junction diodes D\u2081, D\u2082, and D\u2083 are connected across a battery as shown in the figure. If the width of the depletion regions of D\u2081, D\u2082 and D\u2083 are W\u2081, W\u2082 and W\u2083, respectively, then the correct option is:",o:["W\u2083 = W\u2081 > W\u2082","W\u2083 > W\u2082 > W\u2081","W\u2082 > W\u2081 = W\u2083","W\u2081 > W\u2082 > W\u2083"],c:1,s:`D\u2081 is forward biased.
Depletion region of a forward-biased diode (W\u2081) is the minimum.
D\u2083 is reverse biased.
Depletion region of a reverse-biased diode (W\u2083) is the maximum.
D\u2082 is unbiased.
Its depletion region (W\u2082) lies between W\u2081 and W\u2083.
So W\u2083 > W\u2082 > W\u2081.`,fig:{w:250,h:225,alt:"Three branches across a 5 V battery: 1 k\u03A9 with D1 (forward), 1 k\u03A9 with D2 (middle branch not joined to the right wire), and D3 (reversed) with 1 k\u03A9.",d:[["l",47,33,80,33,""],["p","M80 33 L82.7 28 L85.4 38 L88.1 28 L90.8 38 L93.5 28 L96.2 38 L98.8 28 L101.5 38 L104.2 28 L106.9 38 L109.6 28 L112.3 38 L115 33"],["l",115,33,152,33,""],["p","M152 25L152 41L170 33Z","F"],["l",170,25,170,41,""],["l",170,33,204,33,""],["t",77,18,"1 k\u03A9",""],["t",150,16,"D\u2081",""],["l",20,95,80,95,""],["p","M80 95 L82.7 90 L85.4 100 L88.1 90 L90.8 100 L93.5 90 L96.2 100 L98.8 90 L101.5 100 L104.2 90 L106.9 100 L109.6 90 L112.3 100 L115 95"],["l",115,95,152,95,""],["p","M152 87L152 103L170 95Z","F"],["l",170,87,170,103,""],["l",170,95,178,95,""],["c",180,95,1.5,"F"],["c",194,95,1.5,"F"],["l",204,95,232,95,""],["t",77,80,"1 k\u03A9",""],["t",150,78,"D\u2082",""],["l",47,150,82,150,""],["p","M100 142L100 158L82 150Z","F"],["l",82,142,82,158,""],["l",100,150,140,150,""],["p","M140 150 L142.7 145 L145.4 155 L148.1 145 L150.8 155 L153.5 145 L156.2 155 L158.8 145 L161.5 155 L164.2 145 L166.9 155 L169.6 145 L172.3 155 L175 150"],["l",175,150,204,150,""],["t",86,135,"D\u2083",""],["t",140,135,"1 k\u03A9",""],["l",47,33,47,150,""],["l",204,33,204,150,""],["l",20,95,20,193,""],["l",232,95,232,193,""],["l",20,193,122,193,""],["l",128,193,232,193,""],["l",122,184,122,202,""],["l",128,189,128,197,"B"],["t",128,218,"5 V","m"]]}},{id:"neet-2026-q029",pn:29,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Semiconductor Electronics",st:"Zener diode in reverse bias",q:"An ideal Zener diode with breakdown voltage of \u22123 V is reverse biased with a negative input voltage V\u1D62 = \u22125 V. The magnitude of voltage difference between point B and A is:",o:["2 V","1 V","0 V","3 V"],c:0,s:`The input voltage magnitude (5 V) is greater than the Zener voltage magnitude (3 V), so the Zener diode is in breakdown.
The voltage across the Zener is V_zener = 3 V.
Total voltage V_total = 5 V.
The rest of the voltage falls across the resistor between B and A.
|V_BA| = 5 \u2212 3 = 2 V.`,fig:{w:200,h:130,alt:"Rectangular circuit: top wire has point C, a Zener diode, point B, resistor R and point A in order; the bottom wire holds a battery.",d:[["p","M20 40 V110 H92"],["p","M108 110 H180 V40 H170"],["l",92,100,92,120],["l",98,104,98,116,"B"],["l",98,110,108,110],["l",20,40,45,40],["l",45,40,60,40],["p","M60 33 L60 47 M60 33 L57 31 M60 47 L63 49"],["p","M60 40 L74 33 L74 47 Z"],["l",74,40,100,40],["p","M100 40 H108 L111 35 L116 45 L121 35 L126 45 L131 35 L134 40 H170"],["t",45,26,"C","m"],["c",45,40,2.5,"F"],["c",100,40,2.5,"F"],["t",100,26,"B","m"],["t",122,26,"R","m"],["c",165,40,2.5,"F"],["t",165,26,"A","m"],["l",165,40,180,40]]},sfig:{w:200,h:130,alt:"Same circuit: top wire C, Zener diode, B, resistor R, A; battery on the bottom wire.",d:[["p","M20 40 V110 H92"],["p","M108 110 H180 V40 H170"],["l",92,100,92,120],["l",98,104,98,116,"B"],["l",98,110,108,110],["l",20,40,45,40],["l",45,40,60,40],["p","M60 33 L60 47 M60 33 L57 31 M60 47 L63 49"],["p","M60 40 L74 33 L74 47 Z"],["l",74,40,100,40],["p","M100 40 H108 L111 35 L116 45 L121 35 L126 45 L131 35 L134 40 H170"],["t",45,26,"C","m"],["c",45,40,2.5,"F"],["c",100,40,2.5,"F"],["t",100,26,"B","m"],["t",122,26,"R","m"],["c",165,40,2.5,"F"],["t",165,26,"A","m"],["l",165,40,180,40]]}}]})();
